class Solution {
    public boolean isIsomorphic(String s, String t) {
        int[] lastS = new int[128];
        int[] lastT = new int[128];
        for (int i = 0; i < s.length(); i++) {
            int source = s.charAt(i);
            int target = t.charAt(i);
            if (lastS[source] != lastT[target]) return false;
            lastS[source] = i + 1;
            lastT[target] = i + 1;
        }
        return true;
    }
}
